window.AUTH=window.AUTH||{};window.AUTH["17-1229"]={"d":"17-1229","id":"2018/17-1229","n":"Helsinn Healthcare S.A. v. Teva Pharmaceuticals USA Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Helsinn Healthcare S.A.","date":"2018-08-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/60444/20180823120304973_17-1229ts.pdf","side":"pet","n":54},{"k":"united-states","label":"Brief amicus curiae of United States of America","date":"2018-08-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/62207/20180830112539978_17-1229tsacUnitedStates.pdf","side":"us","n":33},{"k":"respondent","label":"Brief of respondents Teva Pharmaceuticals USA, Inc., et al.","date":"2018-10-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/66274/20181009162145270_Helsinn%20v.%20Teva%20--%20FINAL%20BRIEF.PDF","side":"res","n":45},{"k":"reply","label":"Reply of petitioner Helsinn Healthcare S.A.","date":"2018-11-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/71385/20181108095821758_Helsinn%20reply%20brief%20for%20petitioner%20FINAL.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1229_2co3.pdf","tr":true,"items":[{"t":"case","label":"A.B. Chance Co. v. RTE Corp.","cite":"854 F.2d 1307","y":1988,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/854/1307/","by":{"0":"44"}},{"t":"case","label":"August Technology Corp. v. Camtek, Ltd.","cite":"655 F.3d 1278","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1278/","by":{"0":"40"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"ar":1,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"38","2":"32","3":"7"}},{"t":"case","label":"Beachcombers v. WildeWood Creative Products, Inc.","cite":"31 F.3d 1154","y":1994,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/31/1154/","ar":1,"by":{"0":"43"}},{"t":"case","label":"Bonito Boats, Inc. v. Thunder Craft Boats, Inc.","cite":"489 U.S. 141","y":1989,"id":"1988/87-1346","sc":1,"ar":1,"sum":"The Court held that a state statute that contradicts with the public policy behind federal statutes is invalid.","sumSrc":"Oyez","by":{"0":"5, 6, 46, 47","1":"2, 21, 22, 23","2":"7, 47","3":"10"}},{"t":"case","label":"Brenner v. Manson","cite":"383 U.S. 519","y":1966,"id":"1965/58","sc":1,"sum":"In December 1957 Ringold and Rosenkranz applied for a patent on an allegedly novel process for making certain steroids, claiming priority as of December 1956. A patent issued thereon in 1959. In January 1960 respondent filed an application to patent the same process, asserting that he had discovered it prior to December 1956, and requesting that an \"interference\" be declared to test the issue of priority. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Church of the Holy Trinity v. United States","cite":"143 U.S. 457","y":1892,"id":"scdb/1891-129","sc":1,"sum":"The act of February 26, 1885, “ to prohibit the importation and migration of foreigners and aliens under contract.or agreement to perform labor in the United States, its Territories, and the District of Columbia,” 23 Stat. 332, c. 164, does not apply to a contract between an alien, residing out of the United States, and a religious society incorporated under the laws of a State,' whereby he engages to remove to the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"CSX Transportation, Inc. v. Alabama Department of Revenue","cite":"562 U.S. 277","y":2011,"id":"2010/09-520","sc":1,"sum":"The Court held that a railroad company could invoke the Railroad Revitalization and Regulatory Reform Act to challenge sales and use taxes that apply to rail carriers, but exempt their competitors in the transportation industry.","sumSrc":"Oyez","by":{"0":"18, 36"}},{"t":"case","label":"Dart Industries, Inc. v. E.I. du Pont de Nemours & Co.","cite":"489 F.2d 1359","y":1973,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/489/1359/","by":{"0":"44"}},{"t":"case","label":"Federal Maritime Board v. Isbrandtsen Co.","cite":"356 U.S. 481","y":1958,"id":"1957/73","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 36","3":"6"}},{"t":"case","label":"Federal Maritime Commission v. Seatrain Lines, Inc.","cite":"411 U.S. 726","y":1973,"id":"1972/71-1647","sc":1,"sum":"In enacting § 15 of the Shipping Act, 1916, Congress conferred on the Federal Maritime Commission (FMC) the power to exempt 'from the antitrust laws agreements, or those portions of agreements, between carriers that create an ongoing arrangement in which both parties undertake continuing responsibilities, and which therefore necessitate continuous FMC supervision, but not onetime acquisition-of-assets agreements …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","2":"34, 35","3":"3, 6, 7"}},{"t":"case","label":"Federal Trade Commission v. Actavis","cite":"570 U.S. 136","y":2013,"id":"2012/12-416","sc":1,"sum":"The Court found that antitrust law applies to reverse payment agreements.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Graham v. John Deere Co.","cite":"383 U.S. 1","y":1966,"id":"1965/11","sc":1,"sum":"The Court held that the Patent Act of 1952 did not lower the standards required for the patentability of an invention by adding an inquiry into obviousness to the statutory requirements of novelty and utility.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Griffin v. Oceanic Contractors, Inc.","cite":"458 U.S. 564","y":1982,"id":"1981/81-614","sc":1,"sum":"The district courts have no discretion to limit the period during which the wage penalty is assessed. Imposition of the penalty is mandatory for each day that payment is withheld in violation of § 596.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21, 23, 24","1":"18","3":"3, 5"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"566 U.S. 583","y":2012,"id":"2011/10-1542","sc":1,"op":1,"sum":"The Court held that an unemancipated minor cannot use his or her parent's years of residency to fulfill the requirements for having a removal from the country stayed under 8 U.S. C. 1229(a).","sumSrc":"Oyez","by":{"0":"39","3":"9"}},{"t":"case","label":"Kappos v. Hyatt","cite":"566 U.S. 431","y":2012,"id":"2011/10-1219","sc":1,"sum":"The Court held that a patent applicant's ability to introduce new evidence in a civil action against the Patent and Trademark Office was only limited by the Federal Rules of Evidence and the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Kewanee Oil Co. v. Bicron Corp.","cite":"416 U.S. 470","y":1974,"id":"1973/73-187","sc":1,"sum":"Ohio's trade secret law is not pre-empted by the federal patent laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Limelight Networks, Inc. v. Akamai Technologies, Inc.","cite":"134 S. Ct. 2111","y":2014,"id":"2013/12-786","sc":1,"sum":"The Court held that a party is not liable for patent infringement under 35 U.S.C. § 271(b) unless the party has also violated Section 217(a)o or any other statutory provision.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"0":"39"}},{"t":"case","label":"Medicines Co. v. Hospira, Inc.","cite":"827 F.3d 1363","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/827/1363/","by":{"0":"40, 41","2":"9, 48, 54"}},{"t":"case","label":"Minnesota Mining & Manufacturing Co. v. Chemque, Inc.","cite":"303 F.3d 1294","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/303/1294/","by":{"0":"44"}},{"t":"case","label":"New Railhead Manufacturing, L.L.C. v. Vermeer Manufacturing Co.","cite":"298 F.3d 1290","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/298/1290/","by":{"0":"43"}},{"t":"case","label":"OddzOn Products, Inc. v. Just Toys, Inc.","cite":"122 F.3d 1396","y":1997,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/122/1396/","by":{"0":"32"}},{"t":"case","label":"Paroline v. United States","cite":"134 S. Ct. 1710","y":2014,"id":"2013/12-8561","sc":1,"ar":4,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"0":"passim","1":"19, 20","3":"3, 6, 7"}},{"t":"case","label":"Pfaff v. Wells Electronics, Inc.","cite":"525 U.S. 55","y":1998,"id":"1998/97-1130","sc":1,"ar":10,"sum":"Announced by Justice John Paul Stevens, the Court ruled federal patent law does not permit patents to be granted if an invention has been on sale for more than one year in this country before the patent application is filed.","sumSrc":"Oyez","by":{"0":"5, 40, 47","1":"3, 22, 24, 28, 29","2":"passim","3":"8, 10, 16"}},{"t":"case","label":"Puerto Rico v. Franklin California Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"op":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"18, 25"}},{"t":"case","label":"Special Devices, Inc. v. OEA, Inc.","cite":"270 F.3d 1353","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/270/1353/","ar":1,"by":{"0":"5, 41"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"United States v. Standard Brewery","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"ar":2,"sum":"The War-Time Prohibition Act prohibits the use of grains, fruits, and other food products in the.manufacture of “beer, wine, or other intoxicating malt or vinous liquor for beverage purposes,” until the conclusion of the present, war, etc. Held, that the word “intoxicating” qualifies the terms preceding, thus excluding'from the prohibition beer which is not in fact intoxicating.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19, 37","3":"3"}},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"sum":"An apt and sensibl meaning must be given to words as they are used in a statute and the association of words must be regarded as designed and not as accidental, ncSiwill a word be considered an intruder if the statute can be construed reasonably without liminating that word.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19, 37"}},{"t":"law","label":"Pub. L. No. 98-417","url":"https://www.govinfo.gov/link/statute/98/1585","by":{"0":"11"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"0":"passim","1":"2","3":"passim"}},{"t":"law","label":"Pub. L. No. 82-593","url":"https://www.govinfo.gov/link/statute/66/792","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 2259","url":"https://www.law.cornell.edu/uscode/text/18/2259","subs":["(b)(3)(F)","(b)(3)"],"stext":{"head":"§2259. Mandatory restitution","paras":[[0,"(a) In General.—Notwithstanding section 3663 or 3663A, and in addition to any other civil or criminal penalty authorized by law, the court shall order restitution for any offense under this chapter."],[0,"(b) Scope and Nature of Order.—"],[1,"(1) Directions.—Except as provided in paragraph (2), the order of restitution under this section shall direct the defendant to pay the victim (through the appropriate court mechanism) the full amount of the victim's losses."],[1,"(2) Restitution for trafficking in child pornography.—If the defendant was convicted of trafficking in child pornography, the court shall order restitution under this section in an amount to be determined by the court as follows:"],[2,"(A) Determining the full amount of a victim's losses.—The court shall determine the full amount of the victim's losses that were incurred or are reasonably projected to be incurred by the victim as a result of the trafficking in child pornography depicting the victim."],[2,"(B) Determining a restitution amount.—After completing the determination required under subparagraph (A), the court shall order restitution in an amount that reflects the defendant's relative role in the causal process that underlies the victim's losses, but which is no less than $3,000."],[2,"(C) Termination of payment.—A victim's total aggregate recovery pursuant to this section shall not exceed the full amount of the victim's demonstrated losses. After the victim has received restitution in the full amount of the victim's losses as measured by the greatest amount of such losses found in any case involving that victim that has resulted in a final restitution order under this section, the liability of each defendant who is or has been ordered to pay restitution for such losses to that victim shall be terminated. The court may require the victim to provide information concerning the amount of restitution the victim has been paid in other cases for the same losses."],[1,"(3) Enforcement.—An order of restitution under this section shall be issued and enforced in accordance with section 3664 in the same manner as an order under section 3663A."],[1,"(4) Order mandatory.—(A) The issuance of a restitution order under this section is mandatory."],[1,"(B) A court may not decline to issue an order under this section because of—"],[2,"(i) the economic circumstances of the defendant; or"],[2,"(ii) the fact that a victim has, or is entitled to, receive compensation for his or her injuries from the proceeds of insurance or any other source."],[0,"(c) Definitions.—"],[1,"(1) Child pornography production.—For purposes of this section and section 2259A, the term \"child pornography production\" means conduct proscribed by subsections (a) through (c) of section 2251, section 2251A, section 2252A(g) (in cases in which the series of felony violations involves at least 1 of the violations listed in this subsection), section 2260(a), or any offense under chapter 109A or chapter 117 that involved the production of child pornography (as such term is defined in section 2256)."],[1,"(2) Full amount of the victim's losses.—For purposes of this subsection, the term \"full amount of the victim's losses\" includes any costs incurred, or that are reasonably projected to be incurred in the future, by the victim, as a proximate result of the offenses involving the victim, and in the case of trafficking in child pornography offenses, as a proximate result of all trafficking in child pornography offenses involving the same victim, including—"],[2,"(A) medical services relating to physical, psychiatric, or psychological care;"],[2,"(B) physical and occupational therapy or rehabilitation;"],[2,"(C) necessary transportation, temporary housing, and child care expenses;"],[2,"(D) lost income;"],[2,"(E) reasonable attorneys' fees, as well as other costs incurred; and"],[2,"(F) any other relevant losses incurred by the victim."],[1,"(3) Trafficking in child pornography.—For purposes of this section and section 2259A, the term \"trafficking in child pornography\" means conduct proscribed by section 2251(d), 2252, 2252A(a)(1) through (5), 2252A(g) (in cases in which the series of felony violations exclusively involves violations of section 2251(d), 2252, 2252A(a)(1) through (5), or 2260(b)), or 2260(b)."],[1,"(4) Victim.—For purposes of this section, the term \"victim\" means the individual harmed as a result of a commission of a crime under this chapter. In the case of a victim who is under 18 years of age, incompetent, incapacitated, or deceased, the legal guardian of the victim or representative of the victim's estate, another family member, or any other person appointed as suitable by the court, may assume the crime victim's rights under this section, but in no event shall the defendant be named as such representative or guardian."],[0,"(d) Defined Monetary Assistance.—"],[1,"(1) Defined monetary assistance made available at victim's election.—"],[2,"(A) Election to receive defined monetary assistance.—Subject to paragraphs (2) and (3), when a defendant is convicted of trafficking in child pornography, any victim of that trafficking in child pornography may choose to receive defined monetary assistance from the Child Pornography Victims Reserve established under section 1402(d)(6) of the Victims of Crime Act of 1984 (34 U.S.C. 20101(d))."],[2,"(B) Finding.—To be eligible for defined monetary assistance under this subsection, a court shall determine whether the claimant is a victim of the defendant who was convicted of trafficking in child pornography."],[2,"(C) Order.—If a court determines that a claimant is a victim of trafficking in child pornography under subparagraph (B) and the claimant chooses to receive defined monetary assistance, the court shall order payment in accordance with subparagraph (D) to the victim from the Child Pornography Victims Reserve established under section 1402(d)(6) of the Victims of Crime Act of 1984."],[2,"(D) Amount of defined monetary assistance.—The amount of defined monetary assistance payable under this subparagraph shall be equal to—"],[3,"(i) for the first calendar year after the date of enactment of this subsection, $35,000; and"],[3,"(ii) for each calendar year after the year described in clause (i), $35,000 multiplied by the ratio (not less than one) of—"],[4,"(I) the Consumer Price Index for all Urban Consumers (CPI–U, as published by the Bureau of Labor Statistics of the Department of Labor) for the calendar year preceding such calendar year; to"],[4,"(II) the CPI–U for the calendar year 2 years before the calendar year described in clause (i)."],[1,"(2) Limitations on defined monetary assistance.—"],[2,"(A) In general.—A victim may only obtain defined monetary assistance under this subsection once."],[2,"(B) Effect on recovery of other restitution.—A victim who obtains defined monetary assistance under this subsection shall not be barred or limited from receiving restitution against any defendant for any offenses not covered by this section."],[2,"(C) Deduction.—If a victim who received defined monetary assistance under this subsection subsequently seeks restitution under this section, the court shall deduct the amount the victim received in defined monetary assistance when determining the full amount of the victim's losses."],[1,"(3) Limitations on eligibility.—A victim who has collected payment of restitution pursuant to this section in an amount greater than the amount provided for under paragraph (1)(D) shall be ineligible to receive defined monetary assistance under this subsection."],[1,"(4) Attorney fees.—"],[2,"(A) In general.—An attorney representing a victim seeking defined monetary assistance under this subsection may not charge, receive, or collect, and the court may not approve, any payment of fees and costs that in the aggregate exceeds 15 percent of any payment made under this subsection."],[2,"(B) Penalty.—An attorney who violates subparagraph (A) shall be fined under this title, imprisoned not more than 1 year, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2259?type=usc&year=mostrecent&link-type=html"},"head":"§2259. Mandatory restitution","tname":"Crimes and Criminal Procedure","by":{"0":"22","1":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"35 U.S.C. § 100","url":"https://www.law.cornell.edu/uscode/text/35/100","subs":["(j)"],"stext":{"head":"§100. Definitions","paras":[[0,"When used in this title unless the context otherwise indicates—"],[0,"(a) The term \"invention\" means invention or discovery."],[0,"(b) The term \"process\" means process, art or method, and includes a new use of a known process, machine, manufacture, composition of matter, or material."],[0,"(c) The terms \"United States\" and \"this country\" mean the United States of America, its territories and possessions."],[0,"(d) The word \"patentee\" includes not only the patentee to whom the patent was issued but also the successors in title to the patentee."],[0,"(e) The term \"third-party requester\" means a person requesting ex parte reexamination under section 302 who is not the patent owner."],[0,"(f) The term \"inventor\" means the individual or, if a joint invention, the individuals collectively who invented or discovered the subject matter of the invention."],[0,"(g) The terms \"joint inventor\" and \"coinventor\" mean any 1 of the individuals who invented or discovered the subject matter of a joint invention."],[0,"(h) The term \"joint research agreement\" means a written contract, grant, or cooperative agreement entered into by 2 or more persons or entities for the performance of experimental, developmental, or research work in the field of the claimed invention."],[0,"(i)(1) The term \"effective filing date\" for a claimed invention in a patent or application for patent means—"],[1,"(A) if subparagraph (B) does not apply, the actual filing date of the patent or the application for the patent containing a claim to the invention; or"],[1,"(B) the filing date of the earliest application for which the patent or application is entitled, as to such invention, to a right of priority under section 119, 365(a), 365(b), 386(a), or 386(b) or to the benefit of an earlier filing date under section 120, 121, 365(c), or 386(c)."],[0,"(2) The effective filing date for a claimed invention in an application for reissue or reissued patent shall be determined by deeming the claim to the invention to have been contained in the patent for which reissue was sought."],[0,"(j) The term \"claimed invention\" means the subject matter defined by a claim in a patent or an application for a patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/100?type=usc&year=mostrecent&link-type=html"},"head":"§100. Definitions","tname":"Patents","by":{"0":"7, 25, 40","3":"9"}},{"t":"usc","label":"35 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/35/102","subs":["(a)(2006)","(a)(1)","(b)(2006)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(g)(2006)","(a)(1952)","(b)(1952)","(b)(1994)","(b)","(a)"],"stext":{"head":"§102. Conditions for patentability; novelty","paras":[[0,"(a) Novelty; Prior Art.—A person shall be entitled to a patent unless—"],[1,"(1) the claimed invention was patented, described in a printed publication, or in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention; or"],[1,"(2) the claimed invention was described in a patent issued under section 151, or in an application for patent published or deemed published under section 122(b), in which the patent or application, as the case may be, names another inventor and was effectively filed before the effective filing date of the claimed invention."],[0,"(b) Exceptions.—"],[1,"(1) Disclosures made 1 year or less before the effective filing date of the claimed invention.—A disclosure made 1 year or less before the effective filing date of a claimed invention shall not be prior art to the claimed invention under subsection (a)(1) if—"],[2,"(A) the disclosure was made by the inventor or joint inventor or by another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor; or"],[2,"(B) the subject matter disclosed had, before such disclosure, been publicly disclosed by the inventor or a joint inventor or another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor."],[1,"(2) Disclosures appearing in applications and patents.—A disclosure shall not be prior art to a claimed invention under subsection (a)(2) if—"],[2,"(A) the subject matter disclosed was obtained directly or indirectly from the inventor or a joint inventor;"],[2,"(B) the subject matter disclosed had, before such subject matter was effectively filed under subsection (a)(2), been publicly disclosed by the inventor or a joint inventor or another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor; or"],[2,"(C) the subject matter disclosed and the claimed invention, not later than the effective filing date of the claimed invention, were owned by the same person or subject to an obligation of assignment to the same person."],[0,"(c) Common Ownership Under Joint Research Agreements.—Subject matter disclosed and a claimed invention shall be deemed to have been owned by the same person or subject to an obligation of assignment to the same person in applying the provisions of subsection (b)(2)(C) if—"],[1,"(1) the subject matter disclosed was developed and the claimed invention was made by, or on behalf of, 1 or more parties to a joint research agreement that was in effect on or before the effective filing date of the claimed invention;"],[1,"(2) the claimed invention was made as a result of activities undertaken within the scope of the joint research agreement; and"],[1,"(3) the application for patent for the claimed invention discloses or is amended to disclose the names of the parties to the joint research agreement."],[0,"(d) Patents and Published Applications Effective as Prior Art.—For purposes of determining whether a patent or application for patent is prior art to a claimed invention under subsection (a)(2), such patent or application shall be considered to have been effectively filed, with respect to any subject matter described in the patent or application—"],[1,"(1) if paragraph (2) does not apply, as of the actual filing date of the patent or the application for patent; or"],[1,"(2) if the patent or application for patent is entitled to claim a right of priority under section 119, 365(a), 365(b), 386(a), or 386(b), or to claim the benefit of an earlier filing date under section 120, 121, 365(c), or 386(c), based upon 1 or more prior filed applications for patent, as of the filing date of the earliest such application that describes the subject matter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/102?type=usc&year=mostrecent&link-type=html"},"head":"§102. Conditions for patentability; novelty","tname":"Patents","by":{"0":"2, 46, 31, passim, 3, 5, 34, 44, 45, 45, 32","1":"2, 14, 20, 23, passim, 4, 23, 29, 2, 4, 14, 15, 2","2":"passim, 20, 37, 38, 50, 17, 37, 38, 38, 38","3":"passim, 12, 12, 13"}},{"t":"usc","label":"35 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/35/103","by":{"0":"46"}},{"t":"usc","label":"35 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/35/321","subs":["(c)"],"stext":{"head":"§321. Post-grant review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute a post-grant review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the post-grant review."],[0,"(b) Scope.—A petitioner in a post-grant review may request to cancel as unpatentable 1 or more claims of a patent on any ground that could be raised under paragraph (2) or (3) of section 282(b) (relating to invalidity of the patent or any claim)."],[0,"(c) Filing Deadline.—A petition for a post-grant review may only be filed not later than the date that is 9 months after the date of the grant of the patent or of the issuance of a reissue patent (as the case may be)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/321?type=usc&year=mostrecent&link-type=html"},"head":"§321. Post-grant review","tname":"Patents","by":{"0":"34, 35","2":"51"}},{"t":"usc","label":"35 U.S.C. § 326","url":"https://www.law.cornell.edu/uscode/text/35/326","subs":["(a)(5)","(a)(6)","(a)(11)"],"stext":{"head":"§326. Conduct of post-grant review","paras":[[0,"(a) Regulations.—The Director shall prescribe regulations—"],[1,"(1) providing that the file of any proceeding under this chapter shall be made available to the public, except that any petition or document filed with the intent that it be sealed shall, if accompanied by a motion to seal, be treated as sealed pending the outcome of the ruling on the motion;"],[1,"(2) setting forth the standards for the showing of sufficient grounds to institute a review under subsections (a) and (b) of section 324;"],[1,"(3) establishing procedures for the submission of supplemental information after the petition is filed;"],[1,"(4) establishing and governing a post-grant review under this chapter and the relationship of such review to other proceedings under this title;"],[1,"(5) setting forth standards and procedures for discovery of relevant evidence, including that such discovery shall be limited to evidence directly related to factual assertions advanced by either party in the proceeding;"],[1,"(6) prescribing sanctions for abuse of discovery, abuse of process, or any other improper use of the proceeding, such as to harass or to cause unnecessary delay or an unnecessary increase in the cost of the proceeding;"],[1,"(7) providing for protective orders governing the exchange and submission of confidential information;"],[1,"(8) providing for the filing by the patent owner of a response to the petition under section 323 after a post-grant review has been instituted, and requiring that the patent owner file with such response, through affidavits or declarations, any additional factual evidence and expert opinions on which the patent owner relies in support of the response;"],[1,"(9) setting forth standards and procedures for allowing the patent owner to move to amend the patent under subsection (d) to cancel a challenged claim or propose a reasonable number of substitute claims, and ensuring that any information submitted by the patent owner in support of any amendment entered under subsection (d) is made available to the public as part of the prosecution history of the patent;"],[1,"(10) providing either party with the right to an oral hearing as part of the proceeding;"],[1,"(11) requiring that the final determination in any post-grant review be issued not later than 1 year after the date on which the Director notices the institution of a proceeding under this chapter, except that the Director may, for good cause shown, extend the 1-year period by not more than 6 months, and may adjust the time periods in this paragraph in the case of joinder under section 325(c); and"],[1,"(12) providing the petitioner with at least 1 opportunity to file written comments within a time period established by the Director."],[0,"(b) Considerations.—In prescribing regulations under this section, the Director shall consider the effect of any such regulation on the economy, the integrity of the patent system, the efficient administration of the Office, and the ability of the Office to timely complete proceedings instituted under this chapter."],[0,"(c) Patent Trial and Appeal Board.—The Patent Trial and Appeal Board shall, in accordance with section 6, conduct each post-grant review instituted under this chapter."],[0,"(d) Amendment of the Patent.—"],[1,"(1) In general.—During a post-grant review instituted under this chapter, the patent owner may file 1 motion to amend the patent in 1 or more of the following ways:"],[2,"(A) Cancel any challenged patent claim."],[2,"(B) For each challenged claim, propose a reasonable number of substitute claims."],[1,"(2) Additional motions.—Additional motions to amend may be permitted upon the joint request of the petitioner and the patent owner to materially advance the settlement of a proceeding under section 327, or upon the request of the patent owner for good cause shown."],[1,"(3) Scope of claims.—An amendment under this subsection may not enlarge the scope of the claims of the patent or introduce new matter."],[0,"(e) Evidentiary Standards.—In a post-grant review instituted under this chapter, the petitioner shall have the burden of proving a proposition of unpatentability by a preponderance of the evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/326?type=usc&year=mostrecent&link-type=html"},"head":"§326. Conduct of post-grant review","tname":"Patents","by":{"0":"35, 35, 35","3":"18, 18, 18"}},{"t":"reg","label":"78 Fed. Reg. 11,059","url":"https://www.govinfo.gov/link/fr/78/11059","by":{"0":"8"}},{"t":"case","label":"Atlanta Attachment Co. v. Leggett & Platt, Inc.","cite":"516 F.3d 1361","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/516/1361/","by":{"1":"23"}},{"t":"case","label":"Blue Calypso, LLC v. Groupon, Inc.","cite":"815 F.3d 1331","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/815/1331/","by":{"1":"2, 16, 17","3":"5"}},{"t":"case","label":"Consolidated Fruit-Jar Co. v. Wright","cite":"94 U.S. 92","y":1877,"id":"scdb/1876-110","sc":1,"ar":1,"sum":"This is a bill in equity filed by the Consolidated Fruifc-Jar Company to restrain the alleged infringement by the defendant of letters-patent No. 102,918, issued May 10, 1870, to John L. Mason, for an “ improvement in fruit-jars,” and of which the complainant, by mesne assignments, is the owner. The court below, upon hearing, dismissed the bill; whereupon the complainant appealed here.-","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22","2":"2, 25, 52, 54"}},{"t":"case","label":"Egbert v. Lippmann","cite":"104 U.S. 333","y":1881,"id":"scdb/1881-047","sc":1,"sum":"1.- Reissued letters-patent No. 5216, granted Jan. 7,1873, to Frances Lee Barnes, executrix of Samuel H. Barnes, deceased; for an “ improvement in corset-springs,” are void, the invention for which the original letters, bearing date July 17, 1866, were granted, having with his consent been in public use for more than two years prior to his application for them.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Elizabeth v. Pavement Co.","cite":"97 U.S. 126","y":1878,"id":"scdb/1877-248","sc":1,"by":{"1":"22","2":"7","3":"16"}},{"t":"case","label":"Kellogg Co. v. National Biscuit Co.","cite":"305 U.S. 111","y":1938,"id":"scdb/1938-009","sc":1,"sum":"1. The term \"shredded wheat\" is generic, and no exclusive right to its use may be acquired.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Life Techs. Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"sum":"The Court held that supplying a single component of a multi-component invention from the United States for sale abroad does not expose the manufacturer to liability for infringement based on worldwide sales.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Madstad Eng’g, Inc. v. United States Patent & Trademark Office","cite":"756 F.3d 1366","y":2014,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1366/","by":{"1":"24"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Netscape Commc’ns Corp. v. Konrad","cite":"295 F.3d 1315","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1315/","by":{"1":"23"}},{"t":"case","label":"STX, LLC v. Brine, Inc.","cite":"211 F.3d 588","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/211/588/","by":{"1":"23"}},{"t":"case","label":"Scott Paper Co. v. Marcalus Mfg. Co.","cite":"326 U.S. 249","y":1945,"id":"scdb/1945-011","sc":1,"by":{"1":"27"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"17","3":"7"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"usc","label":"35 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/35/1","stext":{"head":"§1. Establishment","paras":[[0,"(a) Establishment.—The United States Patent and Trademark Office is established as an agency of the United States, within the Department of Commerce. In carrying out its functions, the United States Patent and Trademark Office shall be subject to the policy direction of the Secretary of Commerce, but otherwise shall retain responsibility for decisions regarding the management and administration of its operations and shall exercise independent control of its budget allocations and expenditures, personnel decisions and processes, procurements, and other administrative and management functions in accordance with this title and applicable provisions of law. Those operations designed to grant and issue patents and those operations which are designed to facilitate the registration of trademarks shall be treated as separate operating units within the Office."],[0,"(b) Offices.—The United States Patent and Trademark Office shall maintain its principal office in the metropolitan Washington, D.C., area, for the service of process and papers and for the purpose of carrying out its functions. The United States Patent and Trademark Office shall be deemed, for purposes of venue in civil actions, to be a resident of the district in which its principal office is located, except where jurisdiction is otherwise provided by law. The United States Patent and Trademark Office may establish satellite offices in such other places in the United States as it considers necessary and appropriate in the conduct of its business."],[0,"(c) Reference.—For purposes of this title, the United States Patent and Trademark Office shall also be referred to as the \"Office\" and the \"Patent and Trademark Office\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. Establishment","tname":"Patents","by":{"1":"4"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"stext":{"head":"§2. Powers and duties","paras":[[0,"(a) In General.—The United States Patent and Trademark Office, subject to the policy direction of the Secretary of Commerce—"],[1,"(1) shall be responsible for the granting and issuing of patents and the registration of trademarks; and"],[1,"(2) shall be responsible for disseminating to the public information with respect to patents and trademarks."],[0,"(b) Specific Powers.—The Office—"],[1,"(1) shall adopt and use a seal of the Office, which shall be judicially noticed and with which letters patent, certificates of trademark registrations, and papers issued by the Office shall be authenticated;"],[1,"(2) may establish regulations, not inconsistent with law, which—"],[2,"(A) shall govern the conduct of proceedings in the Office;"],[2,"(B) shall be made in accordance with section 553 of title 5;"],[2,"(C) shall facilitate and expedite the processing of patent applications, particularly those which can be filed, stored, processed, searched, and retrieved electronically, subject to the provisions of section 122 relating to the confidential status of applications;"],[2,"(D) may govern the recognition and conduct of agents, attorneys, or other persons representing applicants or other parties before the Office, and may require them, before being recognized as representatives of applicants or other persons, to show that they are of good moral character and reputation and are possessed of the necessary qualifications to render to applicants or other persons valuable service, advice, and assistance in the presentation or prosecution of their applications or other business before the Office;"],[2,"(E) shall recognize the public interest in continuing to safeguard broad access to the United States patent system through the reduced fee structure for small entities under section 41(h)(1);"],[2,"(F) provide for the development of a performance-based process that includes quantitative and qualitative measures and standards for evaluating cost-effectiveness and is consistent with the principles of impartiality and competitiveness; and"],[2,"(G) may, subject to any conditions prescribed by the Director and at the request of the patent applicant, provide for prioritization of examination of applications for products, processes, or technologies that are important to the national economy or national competitiveness without recovering the aggregate extra cost of providing such prioritization, notwithstanding section 41 or any other provision of law;"],[1,"(3) may acquire, construct, purchase, lease, hold, manage, operate, improve, alter, and renovate any real, personal, or mixed property, or any interest therein, as it considers necessary to carry out its functions;"],[1,"(4)(A) may make such purchases, contracts for the construction, maintenance, or management and operation of facilities, and contracts for supplies or services, without regard to the provisions of subtitle I and chapter 33 of title 40, division C (except sections 3302, 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41, and the McKinney-Vento Homeless Assistance Act (42 U.S.C. 11301 et seq.); and"],[1,"(B) may enter into and perform such purchases and contracts for printing services, including the process of composition, platemaking, presswork, silk screen processes, binding, microform, and the products of such processes, as it considers necessary to carry out the functions of the Office, without regard to sections 501 through 517 and 1101 through 1123 of title 44;"],[1,"(5) may use, with their consent, services, equipment, personnel, and facilities of other departments, agencies, and instrumentalities of the Federal Government, on a reimbursable basis, and cooperate with such other departments, agencies, and instrumentalities in the establishment and use of services, equipment, and facilities of the Office;"],[1,"(6) may, when the Director determines that it is practicable, efficient, and cost-effective to do so, use, with the consent of the United States and the agency, instrumentality, Patent and Trademark Office, or international organization concerned, the services, records, facilities, or personnel of any State or local government agency or instrumentality or foreign patent and trademark office or international organization to perform functions on its behalf;"],[1,"(7) may retain and use all of its revenues and receipts, including revenues from the sale, lease, or disposal of any real, personal, or mixed property, or any interest therein, of the Office;"],[1,"(8) shall advise the President, through the Secretary of Commerce, on national and certain international intellectual property policy issues;"],[1,"(9) shall advise Federal departments and agencies on matters of intellectual property policy in the United States and intellectual property protection in other countries;"],[1,"(10) shall provide guidance, as appropriate, with respect to proposals by agencies to assist foreign governments and international intergovernmental organizations on matters of intellectual property protection;"],[1,"(11) may conduct programs, studies, or exchanges of items or services regarding domestic and international intellectual property law and the effectiveness of intellectual property protection domestically and throughout the world, and the Office is authorized to expend funds to cover the subsistence expenses and travel-related expenses, including per diem, lodging costs, and transportation costs, of persons attending such programs who are not Federal employees;"],[1,"(12)(A) shall advise the Secretary of Commerce on programs and studies relating to intellectual property policy that are conducted, or authorized to be conducted, cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) may conduct programs and studies described in subparagraph (A); and"],[1,"(13)(A) in coordination with the Department of State, may conduct programs and studies cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) with the concurrence of the Secretary of State, may authorize the transfer of not to exceed $100,000 in any year to the Department of State for the purpose of making special payments to international intergovernmental organizations for studies and programs for advancing international cooperation concerning patents, trademarks, and other matters."],[0,"(c) Clarification of Specific Powers.—(1) The special payments under subsection (b)(13)(B) shall be in addition to any other payments or contributions to international organizations described in subsection (b)(13)(B) and shall not be subject to any limitations imposed by law on the amounts of such other payments or contributions by the United States Government."],[0,"(2) Nothing in subsection (b) shall derogate from the duties of the Secretary of State or from the duties of the United States Trade Representative as set forth in section 141 of the Trade Act of 1974 (19 U.S.C. 2171)."],[0,"(3) Nothing in subsection (b) shall derogate from the duties and functions of the Register of Copyrights or otherwise alter current authorities relating to copyright matters."],[0,"(4) In exercising the Director's powers under paragraphs (3) and (4)(A) of subsection (b), the Director shall consult with the Administrator of General Services."],[0,"(5) In exercising the Director's powers and duties under this section, the Director shall consult with the Register of Copyrights on all copyright and related matters."],[0,"(d) Construction.—Nothing in this section shall be construed to nullify, void, cancel, or interrupt any pending request-for-proposal let or contract issued by the General Services Administration for the specific purpose of relocating or leasing space to the United States Patent and Trademark Office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/2?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2. Powers and duties","tname":"Patents","by":{"1":"1"}},{"t":"usc","label":"35 U.S.C. § 112","url":"https://www.law.cornell.edu/uscode/text/35/112","subs":["(a)","(b)"],"by":{"1":"3, 16"}},{"t":"usc","label":"35 U.S.C. § 131","url":"https://www.law.cornell.edu/uscode/text/35/131","by":{"1":"1"}},{"t":"case","label":"Air Wisconsin Airlines Corp. v. Hoeper","cite":"571 U.S. 237","y":2014,"id":"2013/12-315","sc":1,"sum":"The Court ruled that the Aviation and Transportation Security Act protects transportation officials from false statements, as long as the statements are not materially false within the ATSA context.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"2":"19, 33"}},{"t":"case","label":"Cont’l Plastic Containers v. Owens Brockway Plastic Prods., Inc.","cite":"141 F.3d 1073","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/141/1073/","by":{"2":"9"}},{"t":"case","label":"D.L. Auld Co. v. Chroma Graphics Corp.","cite":"714 F.2d 1144","y":1983,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/714/1144/","by":{"2":"48"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"2":"28, 29, 32"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"2":"19, 34"}},{"t":"case","label":"Hall v. Macneale","cite":"107 U.S. 90","y":1883,"id":"scdb/1882-127","sc":1,"by":{"2":"25"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"2":"29"}},{"t":"case","label":"Leegin Creative Leather Prods., Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"sum":"The Court ruled 5-4 that \" Dr. Miles should be overruled and that vertical price restraints are to be judged by the rule of reason.\" Justice Anthony Kennedy's majority opinion held that Dr. Miles had erred by treating vertical minimum price agreements between manufacturers and retailers as analogous to horizontal price-fixing agreements between sellers.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"id":"2015/14-8358","sc":1,"sum":"The Court determined that a prior conviction of “aggravated sexual abuse” or “sexual abuse” may trigger a mandatory minimum sentence, even when the prior conviction did not involve a minor.","sumSrc":"Oyez","by":{"2":"30, 36"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"2":"36, 38","3":"6"}},{"t":"case","label":"Merck & Cie v. Watson Labs., Inc.","cite":"822 F.3d 1347","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/822/1347/","by":{"2":"8"}},{"t":"case","label":"Merck KGaA v. Integra Lifesciences I, Ltd.","cite":"545 U.S. 193","y":2005,"id":"2004/03-1237","sc":1,"sum":"The Court reasoned that federal law provided \"a wide berth for the use of patented drugs in activities related to the federal regulatiory process\" and that \"this necessarily included preclinical studies.\" Because federal law required only a \"reasonable relation\" to FDA submission, information gathered on the patented invention (a compound in this case) did not necessarily need to be submitted to the FDA to be exempt from patent protection.","sumSrc":"Oyez","by":{"2":"58"}},{"t":"case","label":"Metallizing Eng’g Co. v. Kenyon Bearing & Auto Parts Co.","cite":"153 F.2d 516","y":1946,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/153/516/","ar":2,"by":{"2":"passim"}},{"t":"case","label":"Midatlantic Nat’l Bank v. N.J. Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"2":"20, 43"}},{"t":"case","label":"Norfolk S. Ry. Co. v. Sorrell","cite":"549 U.S. 158","y":2007,"id":"2006/05-746","sc":1,"sum":"The Court ruled unanimously that the causation standard for employee negligence is the same as the standard for railroad negligence.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Pa. Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"2":"52"}},{"t":"case","label":"Plumtree Software, Inc. v. Datamize, LLC","cite":"473 F.3d 1152","y":2006,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/473/1152/","by":{"2":"48"}},{"t":"case","label":"Russell Motor Car Co. v. United States","cite":"261 U.S. 514","y":1923,"id":"scdb/1922-150","sc":1,"sum":"(a) The word “material” included anti-aircraft gun-mounts for the Navy.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"33, 34","3":"8"}},{"t":"case","label":"S.D. Warren Co. v. Me. Bd. of Envtl. Prot.","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Scaltech, Inc. v. Retec/Tetra, LLC","cite":"269 F.3d 1321","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/269/1321/","by":{"2":"8, 48"}},{"t":"case","label":"Smith & Griggs Mfg. Co. v. Sprague","cite":"123 U.S. 249","y":1887,"id":"scdb/1887-028","sc":1,"by":{"2":"25"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Group Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"2":"27, 28","3":"11"}},{"t":"case","label":"United States v. Reorganized CF&I Fabricators of Utah, Inc.","cite":"518 U.S. 213","y":1996,"id":"1995/95-325","sc":1,"sum":"The Court held that the Internal Revenue Code's 10% tax liability claim on any \"accumulated funding deficiency\" in pension plans, 26 U.S.C. Section 4971(a), does not create an excise tax under the Bankruptcy Code. Additionally, the Court held that the subordination of the Government's tax claim to those of other creditors was an error.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(j)(2)(A)(vii)(IV)"],"by":{"2":"14"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(e)(1)","(e)(2)(A)"],"by":{"2":"58, 14"}},{"t":"usc","label":"35 U.S.C. § 322","url":"https://www.law.cornell.edu/uscode/text/35/322","subs":["(a)(3)"],"by":{"2":"51"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"3":"3, 4, 8"}},{"t":"case","label":"Conroy v. Aniskoff","cite":"507 U.S. 511","y":1993,"id":"1992/91-1353","sc":1,"sum":"When petitioner Conroy, an officer in the United States Army, failed to pay local real estate taxes on property he owned in Danforth, Maine, the town acquired the property and sold it. In his suit against the town and the property's purchasers, Conroy claimed that § 525 of the Soldiers' and Sailors' Civil Relief Act of 1940-which provides that the \"period of military service\" shall not \"be included in computing any …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"13"}},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"sum":"The language \"any money or other property of the United States\" in § 2114 includes the $1,800 belonging to the United States and entrusted to the Secret Service agent as \"flash money,\" and thus by using a pistol in an effort to rob the agent petitioners fell squarely within the prohibitions of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14, 15"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"3":"9, 10"}},{"t":"usc","label":"35 U.S.C. § 273","url":"https://www.law.cornell.edu/uscode/text/35/273","subs":["(a)","(a)(3)(1999)","(e)(1)"],"by":{"3":"19, 20, 20, 20"}}]};